import assert from 'node:assert/strict';
const call=async(path,input)=>{const response=await fetch('http://127.0.0.1:5484/'+path,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(input),signal:AbortSignal.timeout(15000)});if(!response.ok)throw Error(await response.text());return response.json();};
const run=code=>call('eval',{code});
const until=async(code)=>{for(let i=0;i<100;i++){if(await run(code))return;await new Promise(r=>setTimeout(r,50));}throw Error(code);};
const q=label=>JSON.stringify(`[aria-label="${label}"]`);
const click=label=>run(`document.querySelector(${q(label)}).click()`);
const capture=(name,width=1440,height=920)=>call('capture',{name,width,height});
const mode=value=>fetch('http://127.0.0.1:5483/fixture/mode?value='+value);
await run('location.hash="/mail"');await until('!!document.querySelector(".mail-message-row")');
await run('document.querySelector(".mail-message-row").click()');await until('!!document.querySelector(".mail-attachments")');
await capture('after-reader-1100',1100,760);await capture('after-reader-900',900,700);
assert.equal(await run(`document.querySelector('.mail-grid').scrollWidth<=document.querySelector('.mail-grid').clientWidth+1`),true);
await capture('after-reader-760',760,700);
await capture('after-reader-600',600,700);
assert.equal(await run(`getComputedStyle(document.querySelector('.mail-message-list')).display`),'none');
await run(`document.querySelector('.mail-reader-pane>.mail-back').click()`);await capture('after-list-600',600,700);
assert.notEqual(await run(`getComputedStyle(document.querySelector('.mail-message-list')).display`),'none');
await run('document.querySelector(".mail-message-row").click()');await until('!!document.querySelector(".mail-attachments")');
await capture('after-reader',1440,920);
await run(`document.querySelector('[title="View conversation"]').click()`);await until('document.querySelectorAll(".mail-message-row").length===3');await capture('after-conversation');
await run(`Array.from(document.querySelectorAll('button')).find(e=>e.textContent==='Back to inbox').click()`);await until('document.querySelectorAll(".mail-message-row").length===25');
await run(`(()=>{const input=document.querySelector(${q('Search mail')});Object.getOwnPropertyDescriptor(HTMLInputElement.prototype,'value').set.call(input,'agreement');input.dispatchEvent(new Event('input',{bubbles:true}));})()`);
await until('document.querySelectorAll(".mail-search-subject").length===25');await capture('after-search');await capture('after-search-1100',1100,760);
await run(`document.querySelectorAll('.mail-search-subject')[0].dispatchEvent(new MouseEvent('click',{metaKey:true,bubbles:true}));document.querySelectorAll('.mail-search-subject')[3].dispatchEvent(new MouseEvent('click',{metaKey:true,shiftKey:true,bubbles:true}))`);
await until('document.querySelectorAll(".mail-search-hit>input:checked").length===4');
assert.equal(await run(`Array.from(document.querySelectorAll('.mail-search-hit')).every(row=>row.querySelector('input').getBoundingClientRect().right+5<=row.querySelector('.mail-sender').getBoundingClientRect().left)`),true);
await capture('after-search-bulk');await click('Clear search');await until('!!document.querySelector(".mail-message-row")');
await click('Compose');await until('!!document.querySelector("[aria-label=Subject]")');await capture('after-compose',1440,920);await capture('after-compose-1100',1100,760);
await run('location.hash="/settings/mail-accounts"');await until('document.body.innerText.toLowerCase().includes("mail accounts")&&document.body.innerText.includes("mira@example.test")');await capture('after-settings',1440,920);
await mode('small');await run('location.hash="/mail"');await until('document.querySelectorAll(".mail-message-row").length===3');await capture('after-small');
await mode('empty');await click('Refresh mail');await until('document.querySelectorAll(".mail-message-row").length===0&&!document.body.innerText.includes("Loading messages")');await capture('after-empty');
await mode('loading');await click('Refresh mail');await until('document.body.innerText.includes("Loading messages")');await capture('after-loading');
await until('document.querySelectorAll(".mail-message-row").length===25');await mode('error');await click('Refresh mail');await until('!!document.querySelector("[role=alert]")');await capture('after-error');
await mode('large');await click('Refresh mail');await until('document.querySelectorAll(".mail-message-row").length===25');
